WITH with_windows AS (SELECT id, store_id, product_id, quantity, last_restock, SUM(quantity) OVER w_part AS last4_sum_quantity, MIN(quantity) OVER w_part AS last4_min_quantity, MAX(quantity) OVER w_part AS last4_max_quantity, AVG(quantity) OVER w_part AS last4_avg_quantity FROM inventory WHERE product_id IN (3, 6, 8) WINDOW w_part AS (PARTITION BY store_id, product_id ORDER BY quantity, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW)) SELECT s.id, s.store_id, s.quantity, s.last_restock, s.last4_min_quantity, s.last4_avg_quantity, (SELECT MAX(i2.quantity) FROM inventory i2 WHERE i2.store_id = s.store_id) AS max_inventory_quantity FROM with_windows s ORDER BY id DESC NULLS LAST;
